function haystack(app) {
  return [
    app.title,
    app.id,
    app.description,
    app.author
  ].join(" ").toLowerCase();
}

function words(query) {
  return query.trim().toLowerCase().split(" ").filter(word => word !== "");
}

function matches(app, query) {
  let text = haystack(app);
  return words(query).every(word => text.includes(word));
}

function filter(apps, query) {
  if (words(query).length === 0) {
    return apps;
  } else {
    return apps.filter(app => matches(app, query));
  }
}

